-- Agronomy knowledge base + Cortex Search service.
-- Deploy with: .venv/bin/python data/deploy_daily_refresh.py data/setup_advisory_corpus.sql
--
-- 11 crops x 5 topics (sowing_seeds, fertilizer, irrigation, pests_diseases,
-- harvest_market). Content is curated, indicative guidance distilled from
-- public Package of Practices material (PJTSAU/ICAR) — dosages are indicative,
-- not prescriptions; the source column says so. Idempotent: MERGE on chunk_id.

USE ROLE ACCOUNTADMIN;
USE WAREHOUSE KISAN_WH;
USE SCHEMA AGRI.PUBLIC;

CREATE TABLE IF NOT EXISTS AGRI.PUBLIC.ADVISORY_CHUNKS (
  chunk_id STRING,   -- '<crop>:<topic>'
  crop     STRING,
  topic    STRING,   -- sowing_seeds | fertilizer | irrigation | pests_diseases | harvest_market
  region   STRING,
  content  STRING,
  source   STRING
);

MERGE INTO AGRI.PUBLIC.ADVISORY_CHUNKS t
USING (SELECT * FROM VALUES
('cotton:sowing_seeds','Cotton','sowing_seeds','Telangana/Deccan','Sow cotton with the monsoon onset, mid June to mid July. Use approved Bt hybrid seed, about 2 packets of 450 g per acre. Spacing 90 to 105 cm between rows and 60 cm between plants. Treat seed with imidacloprid to delay sucking pests. Do not sow after the end of July because late cotton meets pink bollworm pressure and winter price dips.','PJTSAU/ICAR Package of Practices (indicative)'),
('cotton:fertilizer','Cotton','fertilizer','Telangana/Deccan','Indicative dose 90 to 120 kg N, 60 kg P2O5 and 60 kg K2O per hectare. Apply all P and K basal and split N into 3 or 4 doses at sowing, squaring, flowering and boll development. If leaves redden in September spray 1 percent magnesium sulphate. Excess nitrogen invites sucking pests and boll rot in cloudy weather.','PJTSAU/ICAR Package of Practices (indicative)'),
('cotton:irrigation','Cotton','irrigation','Telangana/Deccan','Cotton tolerates early dry spells but flowering and boll development are the critical water stages, usually 60 to 110 days after sowing. A 10 day dry spell at flowering justifies one protective irrigation if any source exists. Never let water stand in the field; waterlogging for 2 days causes square and boll shedding. Drip with mulch saves about a third of the water.','PJTSAU/ICAR Package of Practices (indicative)'),
('cotton:pests_diseases','Cotton','pests_diseases','Telangana/Deccan','Pink bollworm is the main threat. Set 4 to 5 pheromone traps per acre from flowering; if catches exceed 8 moths per trap for 3 nights spray as per label, and remove and destroy rosette flowers. For jassids and whitefly use neem oil 5 ml per litre first and insecticide only past threshold. Avoid repeated pyrethroids which flare whitefly.','PJTSAU/ICAR Package of Practices (indicative)'),
('cotton:harvest_market','Cotton','harvest_market','Telangana/Deccan','Pick kapas when bolls burst fully open and fibre is dry, usually 3 pickings from October. Keep picked cotton off damp floors to protect staple quality and grade. Compare the mandi modal price with the CCI minimum support price; if the market pays below MSP sell at the nearest CCI procurement centre. Staggered selling over pickings averages out price swings.','PJTSAU/ICAR Package of Practices (indicative)'),
('paddy:sowing_seeds','Paddy (Rice)','sowing_seeds','Telangana/Deccan','For the kharif season raise the nursery in June to early July and transplant 25 to 30 day seedlings, 2 to 3 per hill, at 20 x 15 cm. Seed rate about 20 to 25 kg per acre for transplanting. Treat seed with carbendazim 3 g per kg. If planting is delayed past early August switch to a short duration variety to escape cold at flowering.','PJTSAU/ICAR Package of Practices (indicative)'),
('paddy:fertilizer','Paddy (Rice)','fertilizer','Telangana/Deccan','Indicative dose 120 kg N, 60 kg P2O5 and 40 kg K2O per hectare. Apply P and K basal; split N one third each at basal, active tillering and panicle initiation. In zinc deficient soils showing khaira bronzing apply 50 kg zinc sulphate per hectare once in 3 seasons. Heavy late nitrogen invites brown planthopper and blast.','PJTSAU/ICAR Package of Practices (indicative)'),
('paddy:irrigation','Paddy (Rice)','irrigation','Telangana/Deccan','Keep 2 to 5 cm of standing water from tillering to flowering, the most sensitive stage. Alternate wetting and drying, re-irrigating when water drops 5 cm below the surface in a field tube, saves a quarter of the water without yield loss. Drain the field 10 days before harvest for even ripening and easier machine harvest.','PJTSAU/ICAR Package of Practices (indicative)'),
('paddy:pests_diseases','Paddy (Rice)','pests_diseases','Telangana/Deccan','Watch for stem borer dead hearts and white ears; treat past 5 percent dead hearts. Brown planthopper causes circular hopper burn patches; drain water, open up alleys every 2 metres and avoid excess nitrogen before spraying. For blast neck infection spray tricyclazole at first sign in cloudy humid spells. Rotate chemical groups to avoid resistance.','PJTSAU/ICAR Package of Practices (indicative)'),
('paddy:harvest_market','Paddy (Rice)','harvest_market','Telangana/Deccan','Harvest when 80 percent of grains turn golden, around 30 days after flowering. Harvest at about 20 percent grain moisture and dry to 14 percent for storage and sale; wetter lots get price cuts. Government procurement at IKP and PACS centres pays the MSP for common and grade A paddy; private traders may pay more for fine varieties like Sona Masuri in good years.','PJTSAU/ICAR Package of Practices (indicative)'),
('chilli:sowing_seeds','Chilli','sowing_seeds','Telangana/Deccan','Raise nursery in June to July and transplant 35 to 40 day seedlings in August to early September at 60 x 45 cm. About 200 g of seed raises enough nursery for one acre. Teja and similar hot types dominate export demand. Use virus free seedlings under nylon net nursery to keep early leaf curl out of the main field.','PJTSAU/ICAR Package of Practices (indicative)'),
('chilli:fertilizer','Chilli','fertilizer','Telangana/Deccan','Apply 10 tonnes of farmyard manure per acre before planting. Indicative dose 100 kg N, 50 kg P2O5 and 50 kg K2O per hectare with N in 3 to 4 splits through flowering and fruit set. Too much nitrogen gives lush growth that thrips and mites prefer. Potash improves fruit colour, pungency and keeping quality which decide grade and price.','PJTSAU/ICAR Package of Practices (indicative)'),
('chilli:irrigation','Chilli','irrigation','Telangana/Deccan','Chilli hates both drought and standing water. Irrigate lightly and evenly; flowering and fruit development are the critical stages, and moisture swings cause flower and fruit drop. Drip irrigation with plastic mulch is the standard for quality red chilli. Stop heavy irrigation as fruits ripen so pods dry evenly for picking.','PJTSAU/ICAR Package of Practices (indicative)'),
('chilli:pests_diseases','Chilli','pests_diseases','Telangana/Deccan','Thrips and mites cause upward and downward leaf curl; start with blue sticky traps and neem oil, escalate per label only past threshold. Fruit borer bores ripening pods; pheromone traps plus one biological spray such as NPV help before chemicals. In humid spells watch anthracnose dieback and fruit rot and spray a recommended fungicide combination promptly.','PJTSAU/ICAR Package of Practices (indicative)'),
('chilli:harvest_market','Chilli','harvest_market','Telangana/Deccan','Pick fully red ripe pods in 3 to 4 rounds and dry on clean floors or tarpaulins to 9 or 10 percent moisture; over dried or stained pods lose grade. Uniform deep red colour earns the export premium. Warangal and Khammam yards trade heavily and Guntur sets the benchmark; cold storage lets you hold stock when arrivals crash the price after peak harvest.','PJTSAU/ICAR Package of Practices (indicative)'),
('maize:sowing_seeds','Maize','sowing_seeds','Telangana/Deccan','Sow kharif maize between mid June and mid July with the monsoon. Use single cross hybrid seed at about 8 kg per acre, spacing 60 x 20 cm, one seed per hill. Seed treatment with cyantraniliprole or similar reduces early fall armyworm damage. A pre emergence herbicide such as atrazine keeps the first 30 days weed free, the period that decides yield.','PJTSAU/ICAR Package of Practices (indicative)'),
('maize:fertilizer','Maize','fertilizer','Telangana/Deccan','Indicative dose 120 kg N, 60 kg P2O5 and 40 kg K2O per hectare. Apply P, K and a quarter of N basal, the rest of N in splits at knee high and tasseling stages. Maize is a heavy feeder and nitrogen shortage at tasseling directly cuts grain fill. In zinc deficient soils add 25 kg zinc sulphate per hectare basal.','PJTSAU/ICAR Package of Practices (indicative)'),
('maize:irrigation','Maize','irrigation','Telangana/Deccan','Tasseling, silking and early grain fill are the water critical stages; stress in that fortnight can halve yield. Kharif rain usually suffices but give a protective irrigation if a dry spell crosses 8 to 10 days at silking. Maize cannot stand waterlogging; drain within a day after heavy rain, especially in the first month.','PJTSAU/ICAR Package of Practices (indicative)'),
('maize:pests_diseases','Maize','pests_diseases','Telangana/Deccan','Fall armyworm is the key pest; scout whorls from 10 days after emergence for ragged holes and frass. Under 10 percent damaged plants, drop dry sand or a sand lime mix into whorls; past that spray emamectin benzoate or spinetoram into the whorl in the evening. Stem borer and post flowering stalk rots matter in some seasons; avoid water stress to limit rots.','PJTSAU/ICAR Package of Practices (indicative)'),
('maize:harvest_market','Maize','harvest_market','Telangana/Deccan','Harvest when husks brown and grains show a black layer at the tip, around 20 percent moisture, then dry to 14 percent for sale. Poultry feed mills are the steady buyers and their demand keeps maize prices firmer than most kharif grains. Store dried grain in aerated bags; damp maize gets aflatoxin and outright rejection at feed plants.','PJTSAU/ICAR Package of Practices (indicative)'),
('onion:sowing_seeds','Onion','sowing_seeds','Maharashtra/Deccan/All India','Kharif onion: nursery in May to June, transplant in July. Rabi onion, the main storage crop: nursery October to November, transplant December to January. Seed rate 3 to 4 kg per hectare in raised nursery beds; transplant 6 to 8 week seedlings at 15 x 10 cm. Fresh seed matters because onion seed loses viability within a year.','PJTSAU/ICAR Package of Practices (indicative)'),
('onion:fertilizer','Onion','fertilizer','Maharashtra/Deccan/All India','Apply about 20 tonnes farmyard manure per hectare. Indicative dose 100 kg N, 50 kg P2O5, 50 kg K2O plus 40 to 50 kg sulphur per hectare; sulphur improves pungency and storage life. Give half N basal and the rest in two splits, but stop all nitrogen once bulbs start forming, roughly 60 days, or necks stay thick and bulbs will not store.','PJTSAU/ICAR Package of Practices (indicative)'),
('onion:irrigation','Onion','irrigation','Maharashtra/Deccan/All India','Onion roots are shallow, so give light frequent irrigations; bulb development is the critical stage. Moisture swings split bulbs. Stop irrigation 10 to 15 days before harvest so necks fall and bulbs cure in the field; late watering causes rot in storage and ruins the crop you meant to hold for better prices.','PJTSAU/ICAR Package of Practices (indicative)'),
('onion:pests_diseases','Onion','pests_diseases','Maharashtra/Deccan/All India','Thrips rasp silvery streaks on leaves and can take a third of the yield; monitor with blue sticky traps and spray per label past threshold, adding a sticker since onion leaves are waxy. Purple blotch and Stemphylium blight appear as dark lesions in humid weather; a mancozeb based spray at first sign plus wider spacing for airflow contains them.','PJTSAU/ICAR Package of Practices (indicative)'),
('onion:harvest_market','Onion','harvest_market','Maharashtra/Deccan/All India','Harvest when half the tops fall over naturally. Cure bulbs 3 to 5 days in shade until necks dry, then store in ventilated structures; only well cured rabi onion keeps 4 to 6 months. Lasalgaon and other Nashik yards set the national price signal. Onion prices swing hard with weather news, so staggered sales beat one panic sale.','PJTSAU/ICAR Package of Practices (indicative)'),
('tomato:sowing_seeds','Tomato','sowing_seeds','All India (Deccan leaning)','Raise nursery under nylon net for 25 to 30 days; transplant at 60 x 45 cm. Kharif planting June to July, rabi October to November; hybrids with leaf curl virus tolerance are worth the seed cost where whitefly is common. Stake or trellis indeterminate hybrids early; sprawling plants lose a third of fruit to soil rot and sunscald.','PJTSAU/ICAR Package of Practices (indicative)'),
('tomato:fertilizer','Tomato','fertilizer','All India (Deccan leaning)','Apply 20 to 25 tonnes farmyard manure per hectare. Indicative dose 120 kg N, 80 kg P2O5 and 50 kg K2O per hectare, N and K in splits through fruiting. Blossom end rot, the black sunken patch at the fruit tip, signals calcium shortage aggravated by uneven watering; foliar calcium nitrate plus even moisture prevents it.','PJTSAU/ICAR Package of Practices (indicative)'),
('tomato:irrigation','Tomato','irrigation','All India (Deccan leaning)','Keep soil moisture even; alternating drought and heavy watering cracks fruit and triggers blossom end rot. Drip with mulch is the standard for commercial tomato. Flowering and fruit set are the critical stages; stress then drops flowers wholesale. Avoid overhead irrigation which spreads early blight and speck.','PJTSAU/ICAR Package of Practices (indicative)'),
('tomato:pests_diseases','Tomato','pests_diseases','All India (Deccan leaning)','Fruit borer is the classic loss maker: pheromone traps from flowering, hand pick bored fruit, and use NPV or Bt sprays before chemicals. Whitefly spreads leaf curl virus; yellow sticky traps plus rouging curled plants early slows it. Early blight and late blight need preventive fungicide in cloudy humid spells; do not wait for full blown lesions.','PJTSAU/ICAR Package of Practices (indicative)'),
('tomato:harvest_market','Tomato','harvest_market','All India (Deccan leaning)','Pick at breaker stage, first colour turn, for distant markets and fully red for local sale; breaker fruit travels without crushing. Grade by size and freedom from cracks; mixed lots sell at the lowest grade in the lot. Tomato prices crash and spike within weeks, so nearby processing tie ups or staggered plantings every 3 weeks protect income better than one big flush.','PJTSAU/ICAR Package of Practices (indicative)'),
('potato:sowing_seeds','Potato','sowing_seeds','Indo-Gangetic plains + Deccan rabi','Plant rabi potato October to November when night temperatures drop. Use certified well sprouted seed tubers, about 25 to 30 quintals per hectare, whole or cut with at least two eyes and cured overnight. Spacing 60 x 20 cm on ridges. Degenerated farm saved seed is the single biggest yield killer; replace seed stock every 3 years.','PJTSAU/ICAR Package of Practices (indicative)'),
('potato:fertilizer','Potato','fertilizer','Indo-Gangetic plains + Deccan rabi','Apply 25 tonnes farmyard manure per hectare. Indicative dose 120 kg N, 80 kg P2O5 and 100 kg K2O per hectare; potato is the most potash hungry field crop and K decides tuber size and keeping quality. Give half N basal and half at earthing up around 30 days. Avoid fresh manure near planting which invites scab.','PJTSAU/ICAR Package of Practices (indicative)'),
('potato:irrigation','Potato','irrigation','Indo-Gangetic plains + Deccan rabi','Give light frequent irrigations keeping ridges moist but never flooded; tuber initiation and bulking, roughly 25 to 60 days, are the critical window. Water stress then means small tubers, and heavy swings cause cracks and hollow heart. Stop irrigation 10 days before haulm cutting so skins set firm for digging and storage.','PJTSAU/ICAR Package of Practices (indicative)'),
('potato:pests_diseases','Potato','pests_diseases','Indo-Gangetic plains + Deccan rabi','Late blight can destroy a field in a week of cool cloudy drizzle; spray protectant fungicide before symptoms when such weather is forecast and switch to systemic combinations at first water soaked lesions. Aphids spread viral degeneration of seed stock; control them if you plan to save seed. Cutworms clip young plants at night; treat soil where damage shows.','PJTSAU/ICAR Package of Practices (indicative)'),
('potato:harvest_market','Potato','harvest_market','Indo-Gangetic plains + Deccan rabi','Cut haulms 10 days before digging so skins harden, then dig, shade dry and sort out cut and green tubers. Well cured potato in cold storage at 2 to 4 degrees keeps until off season prices arrive; the storage receipt can also back a pledge loan. Selling straight off the field at peak harvest is usually the worst price of the year.','PJTSAU/ICAR Package of Practices (indicative)'),
('groundnut:sowing_seeds','Groundnut','sowing_seeds','AP/Telangana/Gujarat','Sow kharif groundnut in June to July with the monsoon, rabi in November to December under irrigation. Use about 40 kg of good kernels per acre for bunch types at 30 x 10 cm. Treat seed with rhizobium and trichoderma. Buy fresh seed each season if possible; groundnut seed loses vigour fast in ordinary storage.','PJTSAU/ICAR Package of Practices (indicative)'),
('groundnut:fertilizer','Groundnut','fertilizer','AP/Telangana/Gujarat','Being a legume groundnut needs little nitrogen: indicative 20 kg N, 40 kg P2O5 and 40 kg K2O per hectare basal. The special step is gypsum, about 200 kg per acre broadcast at flowering and pegging; calcium fills the pods and prevents pops, empty shells. Skipping gypsum is the commonest hidden yield loss in groundnut.','PJTSAU/ICAR Package of Practices (indicative)'),
('groundnut:irrigation','Groundnut','irrigation','AP/Telangana/Gujarat','Flowering, pegging and pod development are the critical stages; a dry spell then cuts pod set sharply, so give protective irrigation if rain fails for 10 days in that window. Rabi crops need 6 to 8 irrigations. Keep the pegging zone soil loose and moist; hard dry crusts stop pegs entering the soil at all.','PJTSAU/ICAR Package of Practices (indicative)'),
('groundnut:pests_diseases','Groundnut','pests_diseases','AP/Telangana/Gujarat','Leaf miner and Spodoptera caterpillars defoliate in dry spells; treat past thresholds with recommended insecticides in the evening. Tikka leaf spots and rust brown the canopy from 60 days; one or two sprays of chlorothalonil or hexaconazole protect the leaves that fill pods. White grub areas need chlorpyriphos seed or soil treatment at sowing.','PJTSAU/ICAR Package of Practices (indicative)'),
('groundnut:harvest_market','Groundnut','harvest_market','AP/Telangana/Gujarat','Harvest when older leaves yellow and the inside of the shell shows dark veins with kernels filling the shell. Dry pods in thin layers to 8 to 10 percent moisture; slow damp drying breeds aflatoxin which oil mills and exporters reject outright. Handpicked selected grade for the table market pays well above oil crushing price when kernels are bold and clean.','PJTSAU/ICAR Package of Practices (indicative)'),
('redgram:sowing_seeds','Red Gram (Tur)','sowing_seeds','Telangana/Deccan','Sow red gram with the first good monsoon rains in June to July; late sowing shrinks the plant and the yield. Seed rate 5 to 6 kg per acre; wide spacing of 150 to 180 cm between rows for medium and long duration types allows intercropping with a short legume. Treat seed with rhizobium culture for nodulation on new fields.','PJTSAU/ICAR Package of Practices (indicative)'),
('redgram:fertilizer','Red Gram (Tur)','fertilizer','Telangana/Deccan','As a deep rooted legume red gram needs only a starter dose: indicative 25 kg N and 50 kg P2O5 per hectare basal, plus 25 kg K2O on poor soils. It fixes its own nitrogen after the first month. A foliar spray of 2 percent DAP at flowering and pod fill is a cheap boost where the crop looks pale on shallow soils.','PJTSAU/ICAR Package of Practices (indicative)'),
('redgram:irrigation','Red Gram (Tur)','irrigation','Telangana/Deccan','Red gram is grown rainfed on deep soils, but one or two protective irrigations at flowering and pod filling, usually October to November after the monsoon retreats, can add half again to the yield. It cannot stand waterlogging even for a day; on black soils sow on ridges or beds so August downpours drain away from the root zone.','PJTSAU/ICAR Package of Practices (indicative)'),
('redgram:pests_diseases','Red Gram (Tur)','pests_diseases','Telangana/Deccan','The pod borer complex, Helicoverpa and the spotted pod borer Maruca, decides the harvest. From flower initiation set pheromone traps, spray neem seed kernel extract 5 percent early, and reserve chemicals like emamectin or flubendiamide for threshold crossings at flowering and podding. Choose wilt resistant varieties on fields with a wilt history.','PJTSAU/ICAR Package of Practices (indicative)'),
('redgram:harvest_market','Red Gram (Tur)','harvest_market','Telangana/Deccan','Harvest when about 80 percent of pods turn brown, thresh and sun dry grain to 10 or 11 percent moisture. NAFED procures tur at MSP in notified yards when open prices sag, so check both before selling. Dal mills pay premiums for bold clean grain. Store with dried neem leaves or in airtight bags against bruchid weevils.','PJTSAU/ICAR Package of Practices (indicative)'),
('soybean:sowing_seeds','Soybean','sowing_seeds','MP/Maharashtra/Deccan','Sow soybean between 20 June and 15 July once about 100 mm of monsoon rain has accumulated; dry sowing gambles the costly seed. Seed rate 30 to 35 kg per acre at 45 x 5 cm. Treat seed with rhizobium plus PSB and handle gently, the seed coat cracks easily. On black soils sow on broad bed furrows for drainage.','PJTSAU/ICAR Package of Practices (indicative)'),
('soybean:fertilizer','Soybean','fertilizer','MP/Maharashtra/Deccan','Indicative dose 20 kg N, 60 kg P2O5, 40 kg K2O and 20 kg sulphur per hectare, all basal; as a legume soybean fixes its own nitrogen after establishment and extra urea only feeds weeds. Sulphur matters for oil content which is what the buyer is paying for. Correct zinc and boron where soil tests show deficiency.','PJTSAU/ICAR Package of Practices (indicative)'),
('soybean:irrigation','Soybean','irrigation','MP/Maharashtra/Deccan','Soybean is a rainfed monsoon crop; the real task is drainage, because 2 days of standing water on black soils yellows and kills patches. Broad bed furrows earn their cost in one wet August. If the monsoon breaks for 2 weeks at pod filling, one protective irrigation protects the yield formed to that point.','PJTSAU/ICAR Package of Practices (indicative)'),
('soybean:pests_diseases','Soybean','pests_diseases','MP/Maharashtra/Deccan','Scout for girdle beetle wilted shoot tips and for Spodoptera and semilooper defoliation from a month after sowing; spray per label past thresholds. Whitefly spreads yellow mosaic virus, yellow patches on leaves; rogue infected plants early and control the vector. In prolonged wet spells watch for rust in southern belts and act at the first orange pustules.','PJTSAU/ICAR Package of Practices (indicative)'),
('soybean:harvest_market','Soybean','harvest_market','MP/Maharashtra/Deccan','Harvest when leaves drop and pods rattle, at 13 to 14 percent moisture, and thresh gently to keep seed coats whole. Soybean prices track international oil and meal markets, so the processing plants of MP and Maharashtra set the tone; check the plant delivery rate against your mandi modal price. Clean dry grain avoids the moisture cut every trader applies.','PJTSAU/ICAR Package of Practices (indicative)'),
('wheat:sowing_seeds','Wheat','sowing_seeds','North India rabi','Sow irrigated timely wheat 1 to 20 November; every week of delay past that costs roughly 1 percent of yield per day by the end. Seed rate about 40 kg per acre, line sown 20 cm apart; raise it a quarter for late sowing with short duration varieties. Zero till sowing straight into rice stubble saves a full irrigation and sows earlier.','PJTSAU/ICAR Package of Practices (indicative)'),
('wheat:fertilizer','Wheat','fertilizer','North India rabi','Indicative dose 120 kg N, 60 kg P2O5 and 40 kg K2O per hectare. Apply full P and K with half the N basal, and the remaining N with the first irrigation at crown root initiation, about 21 days; that single top dressing timing matters more than the exact dose. Late sown wheat gets the same N in two closer splits.','PJTSAU/ICAR Package of Practices (indicative)'),
('wheat:irrigation','Wheat','irrigation','North India rabi','Crown root initiation at about 21 days is the make or break irrigation; missing it costs more yield than missing any other. Later waterings at tillering, jointing, flowering and milk stage follow as supply allows, 4 to 6 in all on most soils. Avoid irrigating during strong winds at grain fill, which lodges the crop flat.','PJTSAU/ICAR Package of Practices (indicative)'),
('wheat:pests_diseases','Wheat','pests_diseases','North India rabi','Yellow rust arrives in cool cloudy January weather as powdery yellow stripes; spray propiconazole at the first patch and do not wait, it spreads on the wind. Aphids on ears seldom justify sprays if ladybirds are active. The real yield thief is the weed Phalaris minor; rotate herbicide groups yearly because resistant populations are widespread.','PJTSAU/ICAR Package of Practices (indicative)'),
('wheat:harvest_market','Wheat','harvest_market','North India rabi','Combine harvest when grain is hard and straw golden, around 12 to 14 percent moisture, from late March. Government agencies procure wheat at MSP in April at notified centres, which sets an effective price floor; private trade pays above it for lustrous bold grain in tight years. Clean and dry grain before storage; weevils start in the first damp bag.','PJTSAU/ICAR Package of Practices (indicative)')
  AS v(chunk_id, crop, topic, region, content, source)) s
ON t.chunk_id = s.chunk_id
WHEN MATCHED THEN UPDATE SET
  t.crop = s.crop, t.topic = s.topic, t.region = s.region,
  t.content = s.content, t.source = s.source
WHEN NOT MATCHED THEN INSERT (chunk_id, crop, topic, region, content, source)
  VALUES (s.chunk_id, s.crop, s.topic, s.region, s.content, s.source);

-- Semantic retrieval over the corpus. TARGET_LAG keeps the index fresh after
-- future MERGEs without manual refreshes.
CREATE CORTEX SEARCH SERVICE IF NOT EXISTS AGRI.PUBLIC.ADVISORY_SEARCH
  ON content
  ATTRIBUTES crop, topic, region
  WAREHOUSE = KISAN_WH
  TARGET_LAG = '1 hour'
  AS SELECT chunk_id, crop, topic, region, content, source
     FROM AGRI.PUBLIC.ADVISORY_CHUNKS;
